package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.NullValueProvider;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.StdDeserializer;
import com.fasterxml.jackson.databind.deser.impl.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.ValueInstantiator;
import com.fasterxml.jackson.databind.introspect.AnnotatedWithParams;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.ser.std.ToStringSerializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class StringCollectionDeserializer_createContextual_TriageGen1Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType collectionType;
    private JavaType contentType;

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        collectionType = mock(JavaType.class);
        contentType = mock(JavaType.class);

        when(collectionType.getContentType()).thenReturn(contentType);
        // Mocking config for delegateType call
        com.fasterxml.jackson.databind.DeserializationConfig config = mock(com.fasterxml.jackson.databind.DeserializationConfig.class);
        when(ctxt.getConfig()).thenReturn(config);
    }

    @Test
    public void testCreateContextual_WithDelegateAndValueDeser() throws JsonMappingException {
        // Setup delegate creator
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        com.fasterxml.jackson.databind.deser.impl.StdDeserializer<Object> delegateDeser = mock(com.fasterxml.jackson.databind.deser.StdDeserializer.class);
        com.fasterxml.jackson.databind.deser.impl.StdDeserializer<Object> valueDeser = mock(com.fasterxml.jackson.databind.deser.StdDeserializer.class);

        // Mock AnnotatedWithParams delegate creator
        com.fasterxml.jackson.databind.deser.impl.StdValueInstantiator delegateCreator = mock(com.fasterxml.jackson.databind.deser.impl.StdValueInstantiator.class);
        when(instantiator.getDelegateCreator()).thenReturn(delegateCreator);
        when(instantiator.getDelegateType(any())).thenReturn(contentType);

        // Mock finding delegate deserializer (via findDeserializer which is internal/protected, 
        // but in this context we assume the implementation of StringCollectionDeserializer 
        // uses findDeserializer which we can't easily mock without spying, 
        // so we rely on the logic flow)

        // Setup valueDeser branch: valueDeser != null -> handleSecondaryContextualization
        StringCollectionDeserializer deser = new StringCollectionDeserializer(collectionType, valueDeser, instantiator);

        when(ctxt.handleSecondaryContextualization(eq(valueDeser), eq(property), eq(contentType)))
                .thenReturn(valueDeser);

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).handleSecondaryContextualization(valueDeser, property, contentType);
    }

    @Test
    public void testCreateContextual_NoDelegate_NoValueDeser_FindContextual() throws JsonMappingException {
        // No instantiator, no valueDeser
        StringCollectionDeserializer deser = new StringCollectionDeserializer(collectionType, null, null);

        JsonDeserializer<?> fallbackDeser = mock(JsonDeserializer.class);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(fallbackDeser);

        // Mock findConvertingContentDeserializer returning null
        // Since findConvertingContentDeserializer is protected, we rely on default behavior (null)

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).findContextualValueDeserializer(contentType, property);
    }

    @Test
    public void testCreateContextual_WithDefaultDeserializer() throws JsonMappingException {
        // Setup to trigger isDefaultDeserializer returning true
        // StringCollectionDeserializer is a specific type, but we can pass a standard one
        JsonDeserializer<?> defaultDeser = new StdDeserializer<Object>(Object.class) {};

        StringCollectionDeserializer deser = new StringCollectionDeserializer(collectionType, defaultDeser, null);

        // valueDeser is not null, goes to handleSecondaryContextualization
        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(defaultDeser);

        // isDefaultDeserializer logic: typically checks if it's a standard type
        // For this test, we assume the implementation of isDefaultDeserializer handles it

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);

        // If isDefaultDeserializer(valueDeser) is true, valueDeser becomes null in withResolved
        // Note: Implementation of isDefaultDeserializer is not provided, but we test the path
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_DelegateCreatorNull() throws JsonMappingException {
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        when(instantiator.getDelegateCreator()).thenReturn(null);

        StringCollectionDeserializer deser = new StringCollectionDeserializer(collectionType, null, instantiator);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_ValueDeserIsNull_FindConvertingReturnsValue() throws JsonMappingException {
        StringCollectionDeserializer deser = new StringCollectionDeserializer(collectionType, null, null);

        JsonDeserializer<?> convertingDeser = mock(JsonDeserializer.class);
        // We simulate findConvertingContentDeserializer returning a value by setting up 
        // the behavior if we were spying, but since it's protected, we test the null path
        // to ensure it reaches findContextualValueDeserializer

        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(convertingDeser);

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);
        assertNotNull(result);
    }

    @Test
    public void testCreateContextual_WithNullInstantiator() throws JsonMappingException {
        StringCollectionDeserializer deser = new StringCollectionDeserializer(collectionType, null, null);
        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(mock(JsonDeserializer.class));

        JsonDeserializer<?> result = deser.createContextual(ctxt, property);
        assertNotNull(result);
    }
}
